#!/usr/bin/env bash
# Builds the single-page game from src/ into index.html (assets stay in a/)
# Thai sources live in src/*.js; English variants in src/en/*.js are generated by tools/i18n/gen.js
set -e
cd "$(dirname "$0")"
FILES="engine chibi data story pixel audio ui quest chat xlove quizshow ghost pets scard pxemoji stats"
BUILD=$(cat src/*.js src/en/*.js src/i18n_dict.json src/style.css | md5sum | cut -c1-10)
LAZY="road region" # v1.90: the regional chapter ships as its own file, loaded once the chapter opens
js(){ d=$1; echo 'window.__MTM_RAN=1;'; for f in $FILES; do if [ -f "src/$d$f.js" ]; then cat "src/$d$f.js"; else cat "src/$f.js"; fi; echo; done | grep -v '^if(typeof module'; }
{
echo '<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">'
echo '<title>Muay Thai Moe Demo</title>'
echo '<link rel="manifest" href="manifest.webmanifest"><meta name="theme-color" content="#141020"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="Muay Thai Moe"><link rel="apple-touch-icon" href="a/icon-180.png">'
echo '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Chakra+Petch:wght@500;600;700&family=IBM+Plex+Sans+Thai:wght@400;500;600;700&family=Pixelify+Sans:wght@500;700&display=swap">'
echo '<style>'; cat src/style.css; echo '</style></head><body>'
# v1.91.28: sprite sheets, special moves and NPC portraits the game can quietly fetch ahead of time
ART=$(cd a && ls | grep -E '(_sheet|_special)\.(webp|png)$|^npc_.*\.webp$|^npc_(baiyok|vector_|petchara).*\.png$' | grep -Ev '^(alicia|baibua|tabtim|chaba)_(sheet|special)\.webp$|^npc_(baiyok(_black)?|petchara)\.webp$|_face\.png$' | sed 's/.*/"&"/' | paste -sd, -)
echo "<script>window.__MTM_ART=[$ART];</script>"
# v1.91.144: pets with their own pixel art (a/pet_<kind>.webp)
PETART=$(cd a && ls | grep -E '^pet_[a-z]+\.webp$' | sed 's/^pet_//;s/\.webp$//;s/.*/"&"/' | paste -sd, -)
echo "<script>window.__MTM_PETART=[$PETART];</script>"
echo '<div id="app"></div><div id="live" aria-live="polite" role="status"></div>'
echo '<script type="text/plain" id="js-th">'; js ""; echo '</script>'
echo '<script>'; sed "s/__BUILD__/$BUILD/" src/boot.js; echo '</script>'
echo '</body></html>'
} > index.html
# v1.87: English code and the dictionary are separate files, loaded only when needed
js "en/" > en.js
{ printf "window.__MTM_DICT="; cat src/i18n_dict.json; echo ";"; } > i18n.js; rm -f i18n.json
sed "s/__BUILD__/$BUILD/" src/sw.js > sw.js
lazy(){ d=$1; for f in $LAZY; do if [ -f "src/$d$f.js" ]; then cat "src/$d$f.js"; else cat "src/$f.js"; fi; echo; done | grep -v '^if(typeof module'; }
lazy "" > region.js; lazy "en/" > region-en.js
echo "built index.html en.js i18n.js region.js region-en.js sw.js ($BUILD)"
